package proj

import (
	"os"
	"path/filepath"
	"reflect"
	"testing"
)

func TestCountLines(t *testing.T) {
	root := t.TempDir()
	write := func(p, s string) {
		p = filepath.Join(root, p)
		os.MkdirAll(filepath.Dir(p), 0o755)
		os.WriteFile(p, []byte(s), 0o644)
	}
	// generated by the factory: 3 non-blank lines (blank lines do not count)
	write("internal/handler/shop/handler_gen.go", "// Code generated by factory. DO NOT EDIT.\n\npackage shop\n\nfunc A() {}\n")
	// the factory's header over protoc output: generated, and the toolchain's part
	write("gen/shop/v1/shop.pb.go", "// Code generated by factory from design/shop. DO NOT EDIT.\n// note\n\n// Code generated by protoc-gen-go. DO NOT EDIT.\n\npackage v1\n")
	// hand-written: compute logic, main.go (a marker after the package clause does not count)
	write("internal/handler/shop/get_x_logic.go", "// Logic — implemented by AI.\n\npackage shop\n\n// Code generated by factory. DO NOT EDIT.\nfunc getX() int {\n\treturn 1\n}\n")
	write("cmd/server/main.go", "package main\n\nfunc main() {}\n")
	// tests are not service code
	write("internal/handler/shop/get_x_logic_test.go", "package shop\n")
	write("internal/handler/shop/enums_gen_test.go", "// Code generated by factory. DO NOT EDIT.\npackage shop\n")
	// queries: generated, and one copied from an escape hatch (datasource.sql) → hand
	write("db/queries/shop.list-x.sql", "-- Code generated by factory from specs/shop/list-x/spec.yaml. DO NOT EDIT.\n\n-- name: ListX :many\nSELECT 1;\n")
	write("db/queries/shop.get-y.sql", "-- Code generated by factory from specs/shop/get-y/spec.yaml. DO NOT EDIT.\n\n-- name: GetY :one\nSELECT\n  2;\n")
	// not measured: design, specs, schema
	write("design/shop/领域.yaml", "a: 1\n")
	write("db/schema/shop.sql", "CREATE TABLE x (id int);\n")

	st, err := CountLines(root, map[string]bool{"specs/shop/get-y/spec.yaml": true})
	if err != nil {
		t.Fatal(err)
	}
	if st.Generated != 3+4+3 || st.Tools != 4 {
		t.Fatalf("generated = %d (tools %d), want 10 (tools 4)", st.Generated, st.Tools)
	}
	want := map[string]int{"internal/": 6, "cmd/": 2, "escape-sql": 4}
	if !reflect.DeepEqual(st.Hand, want) {
		t.Fatalf("hand = %v, want %v", st.Hand, want)
	}
	if files := []string{"cmd/server/main.go", "db/queries/shop.get-y.sql", "internal/handler/shop/get_x_logic.go"}; !reflect.DeepEqual(st.HandFiles, files) {
		t.Fatalf("hand files = %v", st.HandFiles)
	}
	if st.HandTotal() != 12 || st.HandRatio() != 12.0/22 || st.HandRatioFactoryOnly() != 12.0/18 {
		t.Fatalf("total %d ratio %v factory-only %v", st.HandTotal(), st.HandRatio(), st.HandRatioFactoryOnly())
	}
}

func TestCountLinesEmptyProject(t *testing.T) {
	st, err := CountLines(t.TempDir(), nil)
	if err != nil || st.Generated != 0 || st.HandTotal() != 0 || st.HandRatio() != 0 {
		t.Fatalf("%+v %v", st, err)
	}
}
